-- =====================================================================
-- SIRVE-P · Domicilio de las casillas 2024 · Nuevo León
-- ---------------------------------------------------------------------
-- 7440 casillas, del anexo de ubicación de casillas del INE.
--
-- Llena direccion, ubicacion (nombre del lugar: escuela, casa de cultura…)
-- y referencia (entre qué calles).
--
-- No hay coordenadas en el anexo. Y no se carga lista nominal: viene por
-- grupo de casillas y al sumarla se cuenta varias veces al elector.
--
-- Requiere los catálogos de 2024.
-- Reejecutable.
-- =====================================================================

SET client_min_messages = warning;

-- 1. Columnas que faltaban
ALTER TABLE sirve.casilla ADD COLUMN IF NOT EXISTS ubicacion  text;
ALTER TABLE sirve.casilla ADD COLUMN IF NOT EXISTS referencia text;

BEGIN;

CREATE TEMP TABLE carga (
    clave       text,
    direccion   text,
    ubicacion   text,
    referencia  text
) ON COMMIT DROP;


-- 2. Volcar sobre las casillas
UPDATE sirve.casilla k
   SET direccion  = v.direccion,
       ubicacion  = v.ubicacion,
       referencia = v.referencia
  FROM carga v
 WHERE k.clave = v.clave;

COMMIT;

-- Comprobación
SELECT count(*) AS casillas,
       count(direccion)  AS con_direccion,
       count(ubicacion)  AS con_ubicacion,
       count(referencia) AS con_referencia
  FROM sirve.casilla
 WHERE clave LIKE '2024-%';

SELECT clave, ubicacion, left(direccion, 60) AS domicilio
  FROM sirve.casilla
 WHERE clave LIKE '2024-%' AND ubicacion IS NOT NULL
 ORDER BY clave
 LIMIT 5;
